mapper.select:
select TFPDT.TOTLE_TRADE_ID totleTradeId, FP2.FINPROD_ID finprodId, FP.FINPROD_MARKET_ID appearMarketId, FP.TRADE_MARKET tradeMarket, FP.FINPROD_ABBR appearMarketAbbr, TFPDT.TRADE_DATE tradeDate, FP2.FINPROD_MARKET_ID finprodMarketId, FP2.FINPROD_ABBR finprodAbbr from TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT LEFT JOIN TRD_FIN_PRODUCT_BARTER_TOTAL TFPBP ON TFPDT.TOTLE_TRADE_ID = TFPBP.TRADE_ID LEFT JOIN FIN_PRODUCT FP ON TFPDT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT FP2 ON TFPBP.FINPROD_ID = FP2.FINPROD_ID
TFPDT.PS = 'T41' AND TFPDT.FINPROD_TYPE2 = 'F01' AND TFPDT.TRADE_STATUS = '01' AND TFPDT.IS_CANCEL = 'N'
AND TFPDT.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND TFPDT.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}

SELECT A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, A.FINPROD_ID, A.FINPROD_ABBR, A.FINPROD_MARKET_ID, 'true' as IS_ADDED FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_ADD B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD C on A.FINPROD_MARKET_ID = C.APPEAR_MARKET_ID
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_MARKET_ID = #{initValue}
AND A.TRADE_MARKET = #{tradeMarket}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG} AND (B.IS_ISSUE_ASSET IS NULL OR B.IS_ISSUE_ASSET = 'N')
AND C.FINPROD_ID IS NULL
UNION
SELECT A.SECID id, A.SECNAME text, A.SECID, A.SECNAME, A.SECID, 'false' as IS_ADDED FROM INTERF_PAYHSRCSECINFO A LEFT JOIN FIN_PRODUCT B ON B.FINPROD_MARKET_ID = A.SECID AND B.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
B.FINPROD_ID IS NULL
AND ( A.SECID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.SECNAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.SECID = #{initValue}
AND A.MARKET2 = #{tradeMarket}

mapper.update:
update FIN_PRODUCT_ADD FPA

    FPA.APPEAR_MARKET_ID = #{appearMarketId,jdbcType=VARCHAR},

where FPA.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

