SELECT
count(1)
FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL WTFPDT

    WTFPDT.FINPROD_ID = 'F01_'||#{appearMarketId,jdbcType=VARCHAR}

        AND WTFPDT.WORKFLOW_ID NOT IN #{workflowId,jdbcType=VARCHAR}

select 
    count (1)
from(
    SELECT
    TPD.FINPROD_ID
    FROM TRD_PRODUCT_DEAL TPD

        TPD.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
        AND TPD.TRADE_DATE = #{tradeDate,jdbcType=DATE}


    UNION

    SELECT
    TFPDT.FINPROD_ID
    FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT

        TFPDT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
        AND TFPDT.TRADE_DATE = #{tradeDate,jdbcType=DATE}


    UNION

    SELECT
    WTPD.FINPROD_ID
    FROM WFL_TRD_PRODUCT_DEAL WTPD

        WTPD.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


    UNION

    SELECT
    WTFPDT.FINPROD_ID
    FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL WTFPDT

        WTFPDT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

)

