    FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL WTFPDT

        WTFPDT.FINPROD_ID = 'F01_'||#{appearMarketId,jdbcType=VARCHAR}
        AND (WTFPDT.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} OR WTFPDT.TRADE_STATUS = '3')

)

